package com.mygdx.game;
import com.badlogic.gdx.*; import com.badlogic.gdx.graphics.*; import com.badlogic.gdx.graphics.g2d.*; import com.badlogic.gdx.graphics.g2d.freetype.FreeTypeFontGenerator; import com.badlogic.gdx.math.*; import com.badlogic.gdx.physics.box2d.*; import com.mygdx.game.screens.*;
public class MyGdxGame extends Game { public SpriteBatch batch; public OrthographicCamera camera; public World world; public Vector3 touch=new Vector3(); public AudioManager audioManager; public BitmapFont commonWhiteFont,largeWhiteFont,commonBlackFont; public GameScreen gameScreen; public MenuScreen menuScreen; public SettingsScreen settingsScreen;
 @Override public void create(){Box2D.init();batch=new SpriteBatch();camera=new OrthographicCamera();camera.setToOrtho(false,GameSettings.SCREEN_WIDTH,GameSettings.SCREEN_HEIGHT);world=new World(new Vector2(0,0),true);audioManager=new AudioManager();FreeTypeFontGenerator g=new FreeTypeFontGenerator(Gdx.files.internal(GameResources.FONT_PATH));commonWhiteFont=font(g,24,Color.WHITE);largeWhiteFont=font(g,48,Color.WHITE);commonBlackFont=font(g,24,Color.BLACK);g.dispose();gameScreen=new GameScreen(this);menuScreen=new MenuScreen(this);settingsScreen=new SettingsScreen(this);setScreen(menuScreen);}
 private BitmapFont font(FreeTypeFontGenerator g,int size,Color color){FreeTypeFontGenerator.FreeTypeFontParameter p=new FreeTypeFontGenerator.FreeTypeFontParameter();p.size=size;p.color=color;return g.generateFont(p);} public void stepWorld(){world.step(1f/60f,6,2);}
 @Override public void dispose(){if(screen!=null)screen.dispose();audioManager.dispose();world.dispose();batch.dispose();commonWhiteFont.dispose();largeWhiteFont.dispose();commonBlackFont.dispose();}
}
